/**
 * Extracts the flagship "Notification preferences" recipe from its four CANONICAL, actually-compiled source
 * files into one generated module the website imports. There is exactly one edited copy of each platform's
 * snippet — the file CI compiles — so the homepage's cross-platform proof can never drift from real, verified
 * source the way a hand-duplicated marketing snippet could.
 *
 *   node scripts/gen-flagship-examples.mjs           (writes the generated file)
 *   node scripts/gen-flagship-examples.mjs --check    (fails if the generated file is stale — CI)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const CHECK = process.argv.includes("--check");
const OUT = `${root}/apps/web/src/registry/flagship-example.generated.ts`;

const SOURCES = {
  react: "apps/web/src/examples/flagship-preferences.tsx",
  swiftui: "packages/ui-swiftui/Tests/KinetixUITests/FlagshipPreferencesPanelTests.swift",
  compose: "packages/ui-compose/ui/src/test/kotlin/com/kinetixui/ui/FlagshipPreferencesPanelTest.kt",
  flutter: "packages/ui-flutter/test/flagship_preferences_panel_test.dart",
};

/** The text between `// kx-flagship:start` and `// kx-flagship:end`, dedented and with the marker lines dropped. */
function extract(relPath) {
  const text = readFileSync(`${root}/${relPath}`, "utf8");
  const start = text.indexOf("kx-flagship:start");
  const end = text.indexOf("kx-flagship:end");
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`${relPath}: missing kx-flagship:start / kx-flagship:end markers`);
  }
  // the body is everything after the start marker's own line, up to (not including) the end marker's line
  const bodyStart = text.indexOf("\n", start) + 1;
  const bodyEnd = text.lastIndexOf("\n", end);
  return text.slice(bodyStart, bodyEnd).replace(/\n+$/, "");
}

const extracted = Object.fromEntries(Object.entries(SOURCES).map(([platform, path]) => [platform, extract(path)]));

for (const [platform, code] of Object.entries(extracted)) {
  if (!code.trim()) throw new Error(`${platform}: extracted an empty snippet from ${SOURCES[platform]}`);
}

const GENERATED = "GENERATED by `pnpm gen:flagship` from the four canonical, CI-compiled example files listed below. Edit those, not this file.";

const body = `/**
 * ${GENERATED}
 *
${Object.entries(SOURCES)
  .map(([platform, path]) => ` * ${platform.padEnd(8)} ${path}`)
  .join("\n")}
 */
export const flagshipExampleSource = {
${Object.entries(extracted)
  .map(([platform, code]) => `  ${platform}: ${JSON.stringify(code)},`)
  .join("\n")}
} as const;

export type FlagshipExamplePlatform = keyof typeof flagshipExampleSource;
`;

if (CHECK) {
  const current = readFileSync(OUT, "utf8");
  if (current !== body) {
    console.error(`✗ ${OUT.replace(root + "/", "")} is stale — run \`pnpm gen:flagship\` and commit the result.`);
    process.exit(1);
  }
  console.log("check:flagship-examples ok — generated file matches the four canonical example files.");
} else {
  writeFileSync(OUT, body);
  console.log(`gen:flagship — wrote ${OUT.replace(root + "/", "")} from ${Object.keys(SOURCES).length} canonical files.`);
}
